package dev.zomboid.tacz;
import java.util.*;
/** Particle atlas sprites must be sampled by the particle render sheet, never the block atlas. */
public final class Visual17 {
 public static String category(String ammo,String type,int pellets){String id=ammo.toLowerCase(Locale.ROOT).replaceAll("[^a-z0-9]","");if(pellets>1||type.equals("shotgun")||id.contains("12g")||id.contains("buckshot"))return "shotgun";if(id.contains("50bmg")||id.contains("338")||id.contains("127x")||id.contains("145x")||id.contains("50ae"))return "heavy";if(id.contains("9mm")||id.contains("45acp")||id.contains("22lr")||id.contains("380"))return "pistol";if(id.contains("556")||id.contains("545")||id.contains("762")||id.contains("308")||id.contains("3006"))return "rifle";if(type.equals("sniper"))return "heavy";if(type.equals("pistol")||type.equals("smg"))return "pistol";return "rifle";}
 public static float markSize(String c){return switch(c){case "pistol"->.065f;case "heavy"->.13f;case "shotgun"->.075f;default->.09f;};}
 public static void apply(Object particle,String ammo,String gun){String type="";int pellets=1;try{Object id=R.call(R.type("net.minecraft.resources.ResourceLocation"),"parse",gun);Optional<?> index=(Optional<?>)R.call(R.type("com.tacz.guns.api.TimelessAPI"),"getCommonGunIndex",id);if(index.isPresent()){type=String.valueOf(R.call(index.get(),"getType"));pellets=((Number)R.call(R.call(index.get(),"getBulletData"),"getBulletAmount")).intValue();}}catch(Exception e){R.warn("impact ammunition metadata",e);}String category=category(ammo,type,pellets);Object mc=R.call(R.type("net.minecraft.client.Minecraft"),"getInstance"),atlasId=R.call(R.type("net.minecraft.resources.ResourceLocation"),"fromNamespaceAndPath","minecraft","textures/atlas/particles.png"),texture=R.call(R.call(mc,"getTextureManager"),"getTexture",atlasId),spriteId=R.call(R.type("net.minecraft.resources.ResourceLocation"),"fromNamespaceAndPath","tacz","bullet_hole_"+category);R.call(particle,"setSprite",R.call(texture,"getSprite",spriteId));R.set(particle,"quadSize",markSize(category));}
 public static void configure(Object particle){R.set(particle,"lifetime",Integer.MAX_VALUE);R.set(particle,"alpha",1.0f);}
 public static float size(Object particle){return ((Number)R.get(particle,"quadSize")).floatValue();}
}
